sysauto_script.script:
(function() {

    /* ======================================================
       CAMPUSMATCH PI RETRY JOB

       Runs every 30 seconds.

       FOUND REPORT FLOW:

       1. CampusMatch requests an on-demand PI refresh
          for Description, Image Attribute and Unique
          Feature Similarity.

       2. The refresh runs asynchronously.

       3. If matching happens before PI is ready,
          the Match remains pi_pending = true.

       4. This job retries those pending Match records.

       5. Once PI returns the required similarity scores,
          recomputeMatch() completes the Match.

       The normal 15-minute PI update schedule remains
       available as a fallback.

       TEMPORARY MEASUREMENT:
       Measures the execution time of recomputeMatch().
    ====================================================== */


    var MATCH_TABLE =
        'x_snc_campusmatch_campusmatch_match';


    var pending =
        new GlideRecord(
            MATCH_TABLE
        );


    pending.addQuery(
        'pi_pending',
        true
    );


    /*
     * Protection against processing
     * too many records in one execution.
     */
    pending.setLimit(
        200
    );


    pending.orderBy(
        'sys_created_on'
    );


    pending.query();


    var attempted =
        0;


    var completed =
        0;


    var stillPending =
        0;


    var orchestrator =
        new CampusMatchMatchOrchestrator();


    while (
        pending.next()
    ) {

        attempted++;


        try {

            /* ==========================================
               TEMPORARY PI RETRY TIMING - START
            ========================================== */

            var retryStartMs =
                new Date().getTime();


            gs.info(
                'CampusMatch PI Retry START | ' +
                'Match=' +
                pending.getDisplayValue(
                    'number'
                ) +
                ' | Epoch=' +
                retryStartMs
            );


            /* ==========================================
               ACTUAL MATCH RECOMPUTATION
            ========================================== */

            var success =
                orchestrator.recomputeMatch(
                    pending.getUniqueValue()
                );


            /* ==========================================
               TEMPORARY PI RETRY TIMING - END
            ========================================== */

            var retryEndMs =
                new Date().getTime();


            var retryElapsedSeconds =
                (retryEndMs - retryStartMs) / 1000;


            gs.info(
                'CampusMatch PI Retry END | ' +
                'Match=' +
                pending.getDisplayValue(
                    'number'
                ) +
                ' | Epoch=' +
                retryEndMs +
                ' | Processing=' +
                retryElapsedSeconds +
                ' seconds' +
                ' | Success=' +
                success
            );


            /* ==========================================
               RESULT COUNTING
            ========================================== */

            if (
                success
            ) {

                completed++;

            }
            else {

                stillPending++;

            }

        }
        catch (ex) {

            stillPending++;


            gs.error(
                'CampusMatch PI Retry Job: ' +
                'Error while processing Match ' +
                pending.getDisplayValue(
                    'number'
                ) +
                '. Error: ' +
                ex.message
            );

        }

    }


    /* ==============================================
       JOB SUMMARY
    ============================================== */

    if (
        attempted > 0
    ) {

        gs.info(
            'CampusMatch PI Retry Job completed. ' +
            'Attempted = ' +
            attempted +
            ', Completed = ' +
            completed +
            ', Still Pending = ' +
            stillPending
        );

    }


})();
